import math
    import random
    import time

    LANGUAGE_WRAPPER = 'Consider a fixed regular {num_sides}-gon with vertices labeled cyclically. For any two vertices, define the step j of the chord joining them as the least positive integer in [1, {half_sides}] congruent to their index difference modulo {num_sides}. Let S be the allowed set of steps {allowed_steps_str}. A rectangle is admissible if each of its four sides lies on a chord line determined by a pair of vertices whose step belongs to S. Equivalently, the rectangle is bounded by choosing two distinct parallel chord lines of some direction and two distinct parallel chord lines of the perpendicular direction. How many distinct admissible rectangles can be formed?'

    class _RNGShim:
def __init__(self, seed: int):
    import random as _random
    self._seed = int(seed)
    self._r = _random.Random(self._seed)

def random(self): return self._r.random()
def uniform(self, a, b): return self._r.uniform(a, b)
def randint(self, a, b): return self._r.randint(a, b)
def randrange(self, *args): return self._r.randrange(*args)
def choice(self, seq): return self._r.choice(seq)
def choices(self, population, weights=None, cum_weights=None, k: int = 1):
    return self._r.choices(population, weights=weights, cum_weights=cum_weights, k=k)
def sample(self, population, k: int): return self._r.sample(population, k)
def shuffle(self, x):
    self._r.shuffle(x)
    return x
def getrandbits(self, k: int): return self._r.getrandbits(k)

    def generator(rng):
# We generate a regular 2n-gon and a nontrivial set S of allowed chord steps.
# Steps j are defined in [1, n], with j=n representing a diameter.
# We ensure the instance yields a substantial but not enormous rectangle count.
def make_instance():
    n = rng.randint(7, 24)  # half-sides; polygon has 2n sides, n>=7 for richness
    num_sides = 2 * n
    # Build odd/even step pools excluding diameter for now
    odd_steps = [j for j in range(1, n) if j % 2 == 1]
    even_steps = [j for j in range(1, n) if j % 2 == 0]
    # Choose counts of odd/even steps to include (ensure both parities present)
    max_odd_pick = max(1, min(len(odd_steps), 5))
    max_even_pick = max(1, min(len(even_steps), 5))
    odd_pick = rng.randint(1, max_odd_pick)
    even_pick = rng.randint(1, max_even_pick)
    chosen_odds = rng.sample(odd_steps, odd_pick)
    chosen_evens = rng.sample(even_steps, even_pick)
    S = set(chosen_odds + chosen_evens)
    # Occasionally include the diameter step n
    if rng.random() < 0.5:
        S.add(n)
    # Optionally include step 1 (already possible via chosen_odds); keep as-is
    allowed_steps = sorted(S)
    # Compute rectangle count via robust formula explained in verifier
    s_even_count = sum(1 for j in allowed_steps if 1 <= j <= n-1 and j % 2 == 0)
    s_odd_count = sum(1 for j in allowed_steps if 1 <= j <= n-1 and j % 2 == 1)
    include_diam = (n in S)
    N_even = 2 * s_even_count + (1 if include_diam and (n % 2 == 0) else 0)
    N_odd = 2 * s_odd_count + (1 if include_diam and (n % 2 == 1) else 0)
    def comb2(x):
        return x * (x - 1) // 2 if x >= 2 else 0
    if n % 2 == 0:
        rectangles = (n // 2) * (comb2(N_even) ** 2 + comb2(N_odd) ** 2)
    else:
        rectangles = n * comb2(N_even) * comb2(N_odd)
    return n, num_sides, allowed_steps, rectangles
# Retry until difficulty and validity thresholds are met
for _ in range(100):
    n, num_sides, allowed_steps, rectangles = make_instance()
    # Enforce nontrivial bounds
    if rectangles >= 60 and rectangles <= 200000:
        allowed_steps_str = ", ".join(str(x) for x in allowed_steps)
        return {
            'num_sides': num_sides,
            'half_sides': n,
            'allowed_steps': allowed_steps,
            'allowed_steps_str': allowed_steps_str
        }
# Fallback: if retries fail, construct a safe instance deterministically
n = 12
num_sides = 24
allowed_steps = [2, 3, 4, 6, 8, 11, 12]
allowed_steps_str = ", ".join(str(x) for x in allowed_steps)
return {
    'num_sides': num_sides,
    'half_sides': n,
    'allowed_steps': allowed_steps,
    'allowed_steps_str': allowed_steps_str
}

    def verifier(assign):
# Verify and compute the number of admissible rectangles.
# A chord step j in [1, n] determines a family of parallel chord lines. For j in [1, n-1],
# each matching orientation contributes exactly 2 distinct parallel chord lines.
# For j = n (diameter), each matching orientation contributes exactly 1 chord line.
# Directions are indexed by midpoint angle classes modulo pi, which we can distinguish by parity.
# The total number of chord lines for an even/odd direction depends only on the parity of j and on whether the diameter is included.
try:
    num_sides = int(assign['num_sides'])
    half_sides = int(assign.get('half_sides', num_sides // 2))
except Exception:
    # invalid types
    return (False, None)
# Domain checks
if num_sides % 2 != 0 or half_sides * 2 != num_sides or half_sides < 6:
    # Must be an even-sided polygon with at least 12 sides
    return (False, None)
# Extract allowed steps
S = None
if 'allowed_steps' in assign:
    try:
        S = list(assign['allowed_steps'])
        # Ensure integers
        S = [int(x) for x in S]
    except Exception:
        return (False, None)
else:
    # Parse from string
    s = str(assign.get('allowed_steps_str', '')).strip()
    if not s:
        return (False, None)
    try:
        S = [int(tok.strip()) for tok in s.split(',') if tok.strip()]
    except Exception:
        return (False, None)
# Validate steps are within [1, n]
n = half_sides
Sset = set()
for j in S:
    if not (1 <= j <= n):
        return (False, None)
    Sset.add(j)
allowed_steps = sorted(Sset)
# Compute counts per parity
s_even_count = sum(1 for j in allowed_steps if 1 <= j <= n-1 and j % 2 == 0)
s_odd_count = sum(1 for j in allowed_steps if 1 <= j <= n-1 and j % 2 == 1)
include_diam = (n in Sset)
N_even = 2 * s_even_count + (1 if include_diam and (n % 2 == 0) else 0)
N_odd = 2 * s_odd_count + (1 if include_diam and (n % 2 == 1) else 0)
# Compute rectangles
def comb2(x):
    return x * (x - 1) // 2 if x >= 2 else 0
if n % 2 == 0:
    answer = (n // 2) * (comb2(N_even) ** 2 + comb2(N_odd) ** 2)
else:
    answer = n * comb2(N_even) * comb2(N_odd)
# Enforce difficulty: require a substantial count and both parities contributing
if answer < 60:
    # Too trivial; generator should avoid such instances
    return (False, None)
if comb2(N_even) == 0 and comb2(N_odd) == 0:
    # No rectangles at all
    return (False, None)
return (True, answer)


    def generate_valid_instance(seed: int, timeout_seconds: float = 10.0):
        """Return dict with assignment/question/answer or raise RuntimeError."""
        start = time.time()
        attempts = 0
        while time.time() - start < timeout_seconds:
            attempts += 1
            rng = _RNGShim(seed + attempts)
            assignment = generator(rng)
            valid, answer = verifier(assignment)
            if valid:
                question = LANGUAGE_WRAPPER.format(**assignment)
                return {
                    "assignment": assignment,
                    "question": question,
                    "answer": answer,
                    "attempts": attempts,
                    "elapsed_seconds": time.time() - start,
                }
        raise RuntimeError("Failed to sample a valid assignment within timeout_seconds")

